35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "postcode")
76	    private String postcode;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @Transient
85	    private boolean declaredHouseholdMember;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    public String getEmail() {
115	        return this.email;
116	    }
117	
118	    public void setEmail(String email) {
119	        this.email = email;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public LocalDate getBirthDate() {
131	        return this.birthDate;
132	    }
133	
134	    public void setBirthDate(LocalDate birthDate) {
135	        this.birthDate = birthDate;
136	    }
137	
138	    public String getCustomerCode() {
139	        return this.customerCode;
140	    }
141	
142	    public void setCustomerCode(String customerCode) {
143	        this.customerCode = customerCode;
144	    }
145	
146	    public String getHouseholdId() {
147	        return this.householdId;
148	    }
149	
150	    public void setHouseholdId(String householdId) {
151	        this.householdId = householdId;
152	    }
153	
154	    public Integer getNamesakeCount() {
155	        return this.namesakeCount;
156	    }
157	
158	    public void setNamesakeCount(Integer namesakeCount) {
159	        this.namesakeCount = namesakeCount;
160	    }
161	
162	    public Boolean getBulkSignupWarning() {
163	        return this.bulkSignupWarning;
164	    }
165	
166	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
167	        this.bulkSignupWarning = bulkSignupWarning;
168	    }
169	
170	    public Integer getHouseholdSize() {
171	        return this.householdSize;
172	    }
173	
174	    public void setHouseholdSize(Integer householdSize) {
175	        this.householdSize = householdSize;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    /**
187	     * Whether this owner deliberately declared, when created, that it shares its
188	     * household with an existing owner (the request's {@code sharesHousehold} flag).
189	     * A declared member is created despite occupying an existing household and is not
190	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
191	     */
192	    @Transient
193	    public boolean isDeclaredHouseholdMember() {
194	        return this.declaredHouseholdMember;
195	    }
196	
197	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
198	        this.declaredHouseholdMember = declaredHouseholdMember;
199	    }
200	
201	    /**
202	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
203	     * existing owner: not a hard duplicate, but sharing that owner's last name and postcode
204	     * while carrying a different telephone. See {@link #getPossibleDuplicateOf()}.
205	     */
206	    public Boolean getPossibleDuplicate() {
207	        return this.possibleDuplicate;
208	    }
209	
210	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
211	        this.possibleDuplicate = possibleDuplicate;
212	    }
213	
214	    /**
215	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
216	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
217	     */
218	    public Integer getPossibleDuplicateOf() {
219	        return this.possibleDuplicateOf;
220	    }
221	
222	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
223	        this.possibleDuplicateOf = possibleDuplicateOf;
224	    }
225	
226	    /**
227	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
228	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
229	     * Derived from the owner's own fields, so it stays consistent with them.
230	     */
231	    @Transient
232	    public String getMembershipNumber() {
233	        if (this.customerCode == null || this.registrationDate == null) {
234	            return null;
235	        }
236	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
237	    }
238	
239	    /**
240	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
241	     * over the digits of the customer code. Derived from the owner's own customer code,
242	     * so it stays consistent with it.
243	     */
244	    @Transient
245	    public Integer getCheckDigit() {
246	        if (this.customerCode == null) {
247	            return null;
248	        }
249	        return LuhnCheckDigit.of(this.customerCode);
250	    }
251	
252	    /**
253	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
254	     * one level is added when an email is on file and one more when the owner is unique
255	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
256	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
257	     */
258	    @Transient
259	    public Integer getMembershipLevel() {
260	        int level = 1;
261	        boolean hasEmail = this.email != null && !this.email.isEmpty();
262	        if (hasEmail) {
263	            level++;
264	        }
265	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
266	        if (unique) {
267	            level++;
268	        }
269	        return Math.min(level, 3);
270	    }
271	
272	    /**
273	     * The owner's locality: the canonical region, taken as the region segment of the
274	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
275	     * consistent with the owner's identity. When no customer code has been assigned yet
276	     * it falls back to resolving the region directly from the postcode and city (see
277	     * {@link RegionResolver}), the same rule the customer code itself is built from.
278	     */
279	    @Transient
280	    public String getLocality() {
281	        if (this.customerCode != null) {
282	            int separator = this.customerCode.indexOf('-');
283	            if (separator > 0) {
284	                return this.customerCode.substring(0, separator);
285	            }
286	        }
287	        return RegionResolver.regionFor(this.postcode, this.city);
288	    }
289	
290	    /**
291	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
292	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
293	     * stays consistent with them.
294	     */
295	    @Transient
296	    public String getContactPreference() {
297	        boolean hasEmail = this.email != null && !this.email.isEmpty();
298	        return hasEmail ? "EMAIL" : "PHONE";
299	    }
300	
301	    /**
302	     * The owner's telephone formatted for human display: the stored E.164 number
303	     * rendered as its country calling code, a space and the national digits grouped
304	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
305	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
306	     * consistent with it. See {@link TelephoneFormatter}.
307	     */
308	    @Transient
309	    public String getTelephoneDisplay() {
310	        return TelephoneFormatter.toDisplay(this.telephone);
311	    }
312	
313	    /**
314	     * The owner's identity key: the single derived value used to detect duplicate owners,
315	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
316	     * Two owners are duplicates only when their whole identity keys are equal, so members
317	     * of one household (sharing a household id) but with different telephones stay distinct.
318	     * Derived from the owner's own fields, so it stays consistent with them.
319	     */
320	    @Transient
321	    public String getIdentityKey() {
322	        String telephonePart = this.telephone == null ? "" : this.telephone;
323	        String emailPart = this.email == null ? "" : this.email;
324	        String householdPart = this.householdId == null ? "" : this.householdId;
325	        return telephonePart + "|" + emailPart + "|" + householdPart;
326	    }
327	
328	    /**
329	     * The owner's age band relative to their registration date: {@code "MINOR"} when
330	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
331	     * Derived from the owner's own birth and registration dates, so it stays consistent
332	     * with them; null until a birth date is on file. See {@link AgeBand}.
333	     */
334	    @Transient
335	    public String getAgeBand() {
336	        if (this.birthDate == null || this.registrationDate == null) {
337	            return null;
338	        }
339	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
340	    }
341	
342	    /**
343	     * Normalize the registration date before persisting: default it to the server's
344	     * current date when none was supplied, then roll it forward onto a business day so
345	     * every newly persisted owner is registered on a weekday.
346	     */
347	    @PrePersist
348	    void normalizeRegistrationDate() {
349	        if (this.registrationDate == null) {
350	            this.registrationDate = LocalDate.now();
351	        }
352	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
353	    }
354	
355	    protected Set<Pet> getPetsInternal() {
356	        if (this.pets == null) {
357	            this.pets = new HashSet<>();
358	        }
359	        return this.pets;
360	    }
361	
362	    protected void setPetsInternal(Set<Pet> pets) {
363	        this.pets = pets;
364	    }
365	
366	    public List<Pet> getPets() {
367	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
368	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
369	        return Collections.unmodifiableList(sortedPets);
370	    }
371	
372	    public void setPets(List<Pet> pets) {
373	        this.pets = new HashSet<>(pets);
374	    }
375	
376	    public void addPet(Pet pet) {
377	        getPetsInternal().add(pet);
378	        pet.setOwner(this);
379	    }
380	
381	    /**
382	     * Return the Pet with the given name, or null if none found for this Owner.
383	     *
384	     * @param name to test
385	     * @return true if pet name is already in use
386	     */
387	    public Pet getPet(String name) {
388	        return getPet(name, false);
389	    }
390	
391	    /**
392	     * Return the Pet with the given name, or null if none found for this Owner.
393	     *
394	     * @param name to test
395	     * @return true if pet name is already in use
396	     */
397	    public Pet getPet(String name, boolean ignoreNew) {
398	        name = name.toLowerCase();
399	        for (Pet pet : getPetsInternal()) {
400	            if (!ignoreNew || !pet.isNew()) {
401	                String compName = pet.getName();
402	                compName = compName.toLowerCase();
403	                if (compName.equals(name)) {
404	                    return pet;
405	                }
406	            }
407	        }
408	        return null;
409	    }
410	
411	    public Pet getPet(Integer petId) {
412	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
413	    }
414	
415	    @Override
416	    public String toString() {
417	        return new ToStringCreator(this)
418	
419	            .append("id", this.getId())
420	            .append("new", this.isNew())
421	            .append("lastName", this.getLastName())
422	            .append("firstName", this.getFirstName())
423	            .append("address", this.address)
424	            .append("city", this.city)
425	            .append("telephone", this.telephone)
426	            .toString();
427	    }
428	}
